export const dashboardWidgetSize = {
    extraSmall: "EXTRA_SMALL",
    small: "SMALL",
    medium: "MEDIUM",
    large: "LARGE",
    extraLarge: "EXTRA_LARGE",
};
/** Build a record-list widget with a typed app/element target. */
export function dashboardRecordsWidget(opts) {
    return { ...opts, type: "records" };
}
/** Build a chart widget and enforce that chart and dashboard share an app owner. */
export function dashboardChartWidget(opts) {
    const { owner: _owner, ...widget } = opts;
    return { ...widget, type: "chart" };
}
